mapper.select:
/* Baim05Mapper.selectDailyUserSlotList */ SELECT '' AS chk , A.CMPNY_CD AS cmpnyCd , A.SITE_CD AS siteCd , A.SITE_NM AS siteNm
, A.SLOT_NO AS slotNo , A.SLOT_TYPE AS slotType , A.SLOT_TYPE_NM AS slotTypeNm
, A.FIXED_YN AS fixedYn , A.EXPIRED AS expired , A.USE_YN AS useYn , A.CURR_USER_CD AS currUserId , A.CURR_USER_NM AS currUserNm
, A.MBL_NO_ENC AS mblNo , A.SLOT_STATUS AS slotStatus , A.SLOT_STATUS_NM AS slotStatusNm FROM ( SELECT A.CMPNY_CD , A.SITE_CD , FNC_CMM_INFO_SRCH(A.CMPNY_CD, 'SITE', A.SITE_CD, NULL) AS SITE_NM , A.SLOT_NO , A.SLOT_TYPE , FNC_CMM_INFO_SRCH( A.CMPNY_CD , 'SYST_VAL' , A.SLOT_TYPE , 'SYS014' ) AS SLOT_TYPE_NM , A.FIXED_YN , CASE WHEN SLOT_STATUS = '01' THEN '-' ELSE CASE WHEN FIXED_YN = 'Y' THEN '점유 유지 중' ELSE TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL 1 DAY)) END END EXPIRED , A.USE_YN , A.CURR_USER_CD , B.USER_NM AS CURR_USER_NM , B.MBL_NO_ENC , A.SLOT_STATUS , FNC_CMM_INFO_SRCH( A.CMPNY_CD , 'SYST_VAL' , A.SLOT_TYPE , 'SYS015' ) AS SLOT_STATUS_NM FROM TB_DAILY_USER_SLOT A LEFT OUTER JOIN TB_DAILY_USER B ON ( A.CMPNY_CD = B.CMPNY_CD AND A.SITE_CD = B.SITE_CD AND A.CURR_USER_CD = B.USER_CD AND B.USE_YN = 'Y' ) WHERE A.CMPNY_CD = #{gvCmpnyCd}
AND A.SITE_CD = #{siteCd}
AND A.SLOT_TYPE = #{slotType}
AND A.SLOT_STATUS = #{slotStatus}
AND A.USE_YN = #{useYn}
) A WHERE 1=1
AND A.CURR_USER_NM LIKE CONCAT('%', #{currUserNm}, '%')
ORDER BY SITE_CD, CAST(A.SLOT_NO AS UNSIGNED)

mapper.update:
	/* Baim05Mapper.saveDailyUserLinkPolicy */
    INSERT INTO TB_DAILY_USER_LINK_POLICY (
    	CMPNY_CD
    	, SITE_CD
    	, USE_YN
    	, DAY_LIMIT_CNT
    	, INSERT_NO
    	, INSERT_DATE
    	, UPDATE_NO
    	, UPDATE_DATE
   	)
   	VALUES(
   		#{gvCmpnyCd}
   		, #{siteCd}
		, IFNULL(#{useYn}, 'Y')
		, #{dayLimitCnt}
		, #{gvUserCd}
		, now()
		, #{gvUserCd}
		, now() 
   	) AS NEW
   	ON DUPLICATE KEY UPDATE
	    USE_YN			= IFNULL(NEW.USE_YN, 'Y')
	    , DAY_LIMIT_CNT = NEW.DAY_LIMIT_CNT
	    , UPDATE_NO   	= NEW.UPDATE_NO
	    , UPDATE_DATE 	= NOW()

mapper.select:
    /* Baim05Mapper.selectDailyUserSlotCnt */
    SELECT COUNT(*)
    FROM TB_DAILY_USER_SLOT
	WHERE CMPNY_CD = #{gvCmpnyCd}
	  AND SITE_CD = #{siteCd}

mapper.update:
	/* Baim05Mapper.saveDailyUserSlot */
	INSERT INTO TB_DAILY_USER_SLOT (
    	CMPNY_CD
    	, SITE_CD
    	, SLOT_NO
    	, SLOT_TYPE
    	, FIXED_YN
    	, USE_YN
    	, CURR_USER_CD
    	, SLOT_STATUS
    	, INSERT_NO
    	, INSERT_DATE
    	, UPDATE_NO
    	, UPDATE_DATE
   	)
   	VALUES(
   		#{gvCmpnyCd}
   		, #{siteCd}
   		, #{slotNo}
   		, #{slotType}
   		, 'N'
		, #{useYn}
		, ''
		, #{slotStatus}
		, #{gvUserCd}
		, now()
		, #{gvUserCd}
		, now() 
   	) AS NEW
   	ON DUPLICATE KEY UPDATE
   		USE_YN		= IFNULL(NEW.USE_YN, 'Y')
   		, SLOT_TYPE     = IF(NEW.USE_YN = 'N', '01', TB_DAILY_USER_SLOT.SLOT_TYPE)
	    , CURR_USER_CD  = IF(NEW.USE_YN = 'N', NULL, TB_DAILY_USER_SLOT.CURR_USER_CD)
	    , SLOT_STATUS   = IF(NEW.USE_YN = 'N', '01', TB_DAILY_USER_SLOT.SLOT_STATUS)
	    , UPDATE_NO   	= NEW.UPDATE_NO
	    , UPDATE_DATE 	= NOW()

mapper.select:
/* Baim05Mapper.selectDailyUserCd */
SELECT CONCAT('D', DATE_FORMAT(NOW(), '%Y%m%d'), FNC_CMM_SEQ_NEXTVAL(#{cmpnyCd}, 'DAILY_USER'))
FROM DUAL

	/* Baim05Mapper.selectDailyUserDuplicateCnt */
	SELECT COUNT(*) 
	FROM (
        SELECT 1
          FROM TB_DAILY_USER
         WHERE MBL_NO_HMAC = #{mblNoHmac}
           AND USE_YN      = 'Y'
         LIMIT 1
    ) T

mapper.insert:
	/* Baim05Mapper.insertDailyQrUser */
	INSERT INTO TB_DAILY_USER
	(
		CMPNY_CD
        , SITE_CD
        , USER_CD
        , USER_ID
        , USER_NM
        , USER_PW

        , MBL_NO_ENC
        , MBL_NO_HMAC
        , MBL_NO_LAST4
        , REG_TYPE

        , USE_YN
        , ACCOUNT_STATUS
        , WORK_EXPIRE_DATE
        , WITHDRAWAL_DATE

        , INSERT_NO
        , INSERT_DATE
        , UPDATE_NO
        , UPDATE_DATE
	)
	VALUES
	(
		#{gvCmpnyCd}
		, #{siteCd}
		, #{userCd}
		, #{userCd}					
		, #{userNm}
		, #{userPw}

		, #{mblNoEnc}
		, #{mblNoHmac}
		, #{mblNoLast4}
		, #{regType}

		, #{useYn}
		, #{accountStatus}
		, DATE_FORMAT(NOW(), '%Y%m%d')
		, NULL

		, #{gvUserCd}
		, NOW()
		, #{gvUserCd}
		, NOW()
	)

/* Baim05Mapper.updateDailyUserSlotCurrUserCd */
UPDATE TB_DAILY_USER_SLOT
SET CURR_USER_CD = #{userCd}
	, SLOT_TYPE = #{slotType}
	, SLOT_STATUS =#{slotStatus}
    , UPDATE_NO = #{gvUserCd}
    , UPDATE_DATE = NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SITE_CD = #{siteCd}
  AND SLOT_NO = #{slotNo}
